/**
 * TERRA BELLUM — cached geometry factory for the WebGL layer.
 *
 * Everything the map and battle renderers draw is built here so that a single
 * shape is uploaded to the GPU once and shared by every instance that needs it.
 * Builders are keyed by their parameters; `disposeGeometryCache()` releases the
 * whole pool on teardown.
 *
 * IMPORTANT: geometries handed out by the cache are SHARED. If a caller needs
 * to attach per-instance attributes (InstancedBufferAttribute), it must
 * `.clone()` first — or use {@link InstancedBatch}, which does that for you.
 */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

/**
 * Values written into the hex prism's `aFace` attribute so shaders can tell
 * which part of the prism they are shading.
 *   1.0 = flat top face, 0.5 = bevelled rim, 0.0 = vertical side wall.
 */
export const HEX_FACE = { side: 0, bevel: 0.5, top: 1 } as const;

const TAU = Math.PI * 2;

// ─────────────────────────────────────────────────────────────────────────────
// Cache
// ─────────────────────────────────────────────────────────────────────────────

const cache = new Map<string, THREE.BufferGeometry>();

function cached(key: string, build: () => THREE.BufferGeometry): THREE.BufferGeometry {
  const hit = cache.get(key);
  if (hit) return hit;
  const geo = build();
  geo.name = key;
  cache.set(key, geo);
  return geo;
}

/** Releases every cached geometry. Call once on full renderer teardown. */
export function disposeGeometryCache(): void {
  for (const geo of cache.values()) geo.dispose();
  cache.clear();
}

/** Number of geometries currently pooled (diagnostics / tests). */
export function geometryCacheSize(): number {
  return cache.size;
}

// ─────────────────────────────────────────────────────────────────────────────
// Hex prism — pointy-top, flat top face, bevelled rim
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Pointy-top hexagonal prism with a flat top face and a bevelled rim.
 *
 * Built with `height = 1` by default so an InstancedMesh can scale Y per
 * instance for terrain elevation (the shader re-normalises the normal).
 *
 * UVs: the top face and the bevel are mapped radially — `uv * 2 - 1` gives
 * local hex coordinates where the outer edge of the FLAT TOP sits at hex
 * distance 1.0 and the outer edge of the bevel at ~1/(1-bevel). Side walls use
 * (u = position around the perimeter, v = height fraction).
 */
export function hexPrismGeometry(radius = 1, height = 1, bevel = 0.15): THREE.BufferGeometry {
  return cached(`hexPrism|${radius}|${height}|${bevel}`, () => {
    const rTop = radius * (1 - bevel);
    const yTop = height;
    const yBevel = height * (1 - bevel * 1.35);

    const pos: number[] = [];
    const nrm: number[] = [];
    const uvs: number[] = [];
    const face: number[] = [];

    const ang = (k: number): number => Math.PI / 2 + (k * Math.PI) / 3;

    const push = (
      x: number,
      y: number,
      z: number,
      nx: number,
      ny: number,
      nz: number,
      u: number,
      v: number,
      f: number,
    ): void => {
      pos.push(x, y, z);
      nrm.push(nx, ny, nz);
      uvs.push(u, v);
      face.push(f);
    };

    const radialUv = (x: number, z: number): [number, number] => [
      (x / rTop) * 0.5 + 0.5,
      (z / rTop) * 0.5 + 0.5,
    ];

    // ── top face: triangle fan (centre, rim[k+1], rim[k]) → +Y normal
    for (let k = 0; k < 6; k++) {
      const a0 = ang(k);
      const a1 = ang(k + 1);
      const x0 = rTop * Math.cos(a0);
      const z0 = rTop * Math.sin(a0);
      const x1 = rTop * Math.cos(a1);
      const z1 = rTop * Math.sin(a1);
      const c = radialUv(0, 0);
      const p0 = radialUv(x0, z0);
      const p1 = radialUv(x1, z1);
      push(0, yTop, 0, 0, 1, 0, c[0], c[1], HEX_FACE.top);
      push(x1, yTop, z1, 0, 1, 0, p1[0], p1[1], HEX_FACE.top);
      push(x0, yTop, z0, 0, 1, 0, p0[0], p0[1], HEX_FACE.top);
    }

    // ── bevel ring + side walls, six flat facets each
    const run = radius - rTop;
    const drop = yTop - yBevel;
    for (let k = 0; k < 6; k++) {
      const a0 = ang(k);
      const a1 = ang(k + 1);
      const am = (a0 + a1) * 0.5;
      const ox = Math.cos(am);
      const oz = Math.sin(am);

      // bevel facet normal: outward * drop + up * run, normalised
      const bl = Math.hypot(drop, run) || 1;
      const bnx = (ox * drop) / bl;
      const bny = run / bl;
      const bnz = (oz * drop) / bl;

      const tx0 = rTop * Math.cos(a0);
      const tz0 = rTop * Math.sin(a0);
      const tx1 = rTop * Math.cos(a1);
      const tz1 = rTop * Math.sin(a1);
      const sx0 = radius * Math.cos(a0);
      const sz0 = radius * Math.sin(a0);
      const sx1 = radius * Math.cos(a1);
      const sz1 = radius * Math.sin(a1);

      const ut0 = radialUv(tx0, tz0);
      const ut1 = radialUv(tx1, tz1);
      const us0 = radialUv(sx0, sz0);
      const us1 = radialUv(sx1, sz1);

      // bevel quad (T0, S1, S0) + (T0, T1, S1)
      push(tx0, yTop, tz0, bnx, bny, bnz, ut0[0], ut0[1], HEX_FACE.bevel);
      push(sx1, yBevel, sz1, bnx, bny, bnz, us1[0], us1[1], HEX_FACE.bevel);
      push(sx0, yBevel, sz0, bnx, bny, bnz, us0[0], us0[1], HEX_FACE.bevel);

      push(tx0, yTop, tz0, bnx, bny, bnz, ut0[0], ut0[1], HEX_FACE.bevel);
      push(tx1, yTop, tz1, bnx, bny, bnz, ut1[0], ut1[1], HEX_FACE.bevel);
      push(sx1, yBevel, sz1, bnx, bny, bnz, us1[0], us1[1], HEX_FACE.bevel);

      // side quad (S0, B1, B0) + (S0, S1, B1)
      const u0 = k / 6;
      const u1 = (k + 1) / 6;
      push(sx0, yBevel, sz0, ox, 0, oz, u0, 1, HEX_FACE.side);
      push(sx1, 0, sz1, ox, 0, oz, u1, 0, HEX_FACE.side);
      push(sx0, 0, sz0, ox, 0, oz, u0, 0, HEX_FACE.side);

      push(sx0, yBevel, sz0, ox, 0, oz, u0, 1, HEX_FACE.side);
      push(sx1, yBevel, sz1, ox, 0, oz, u1, 1, HEX_FACE.side);
      push(sx1, 0, sz1, ox, 0, oz, u1, 0, HEX_FACE.side);
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setAttribute('aFace', new THREE.Float32BufferAttribute(face, 1));
    geo.computeBoundingSphere();
    geo.computeBoundingBox();
    return geo;
  });
}

/** Flat pointy-top hexagon lying in the XZ plane (radial UVs, +Y normal). */
export function hexPlateGeometry(radius = 1): THREE.BufferGeometry {
  return cached(`hexPlate|${radius}`, () => {
    const pos: number[] = [];
    const nrm: number[] = [];
    const uvs: number[] = [];
    const face: number[] = [];
    const ang = (k: number): number => Math.PI / 2 + (k * Math.PI) / 3;
    for (let k = 0; k < 6; k++) {
      const a0 = ang(k);
      const a1 = ang(k + 1);
      const x0 = radius * Math.cos(a0);
      const z0 = radius * Math.sin(a0);
      const x1 = radius * Math.cos(a1);
      const z1 = radius * Math.sin(a1);
      pos.push(0, 0, 0, x1, 0, z1, x0, 0, z0);
      nrm.push(0, 1, 0, 0, 1, 0, 0, 1, 0);
      uvs.push(
        0.5,
        0.5,
        (x1 / radius) * 0.5 + 0.5,
        (z1 / radius) * 0.5 + 0.5,
        (x0 / radius) * 0.5 + 0.5,
        (z0 / radius) * 0.5 + 0.5,
      );
      face.push(HEX_FACE.top, HEX_FACE.top, HEX_FACE.top);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setAttribute('aFace', new THREE.Float32BufferAttribute(face, 1));
    geo.computeBoundingSphere();
    return geo;
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Army chevron token
// ─────────────────────────────────────────────────────────────────────────────

type Pt = [number, number];

/** Builds a closed Shape from a polygon with quadratic-rounded corners. */
function roundedShape(pts: Pt[], round: number): THREE.Shape {
  const n = pts.length;
  const shape = new THREE.Shape();
  const lerpTo = (a: Pt, b: Pt, d: number): Pt => {
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dx, dy) || 1;
    const t = Math.min(d, len * 0.45) / len;
    return [a[0] + dx * t, a[1] + dy * t];
  };
  for (let i = 0; i < n; i++) {
    const prev = pts[(i - 1 + n) % n];
    const cur = pts[i];
    const next = pts[(i + 1) % n];
    const a = lerpTo(cur, prev, round);
    const b = lerpTo(cur, next, round);
    if (i === 0) shape.moveTo(a[0], a[1]);
    else shape.lineTo(a[0], a[1]);
    shape.quadraticCurveTo(cur[0], cur[1], b[0], b[1]);
  }
  shape.closePath();
  return shape;
}

/**
 * Rounded chevron / arrowhead army token. Lies in the XZ plane, nose toward
 * +Z, centred on its own bounding box, base at y = 0.
 */
export function armyChevronGeometry(size = 1): THREE.BufferGeometry {
  return cached(`chevron|${size}`, () => {
    const shape = roundedShape(
      [
        [0, 1.02],
        [0.82, -0.62],
        [0, -0.2],
        [-0.82, -0.62],
      ],
      0.24,
    );
    const geo = new THREE.ExtrudeGeometry(shape, {
      depth: 0.34,
      bevelEnabled: true,
      bevelThickness: 0.07,
      bevelSize: 0.07,
      bevelOffset: 0,
      bevelSegments: 2,
      curveSegments: 6,
    });
    // Shape +Y (the nose) → world +Z; the extrusion depth falls to -Y and is
    // lifted back onto the ground plane below.
    geo.rotateX(Math.PI / 2);
    geo.computeBoundingBox();
    const bb = geo.boundingBox;
    if (bb) geo.translate(0, -bb.min.y, 0);
    geo.scale(size, size, size);
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
    return geo;
  });
}

/** Elongated diamond marker (flag pins, mark markers, intel pips). */
export function diamondMarkerGeometry(size = 1): THREE.BufferGeometry {
  return cached(`diamond|${size}`, () => {
    const geo = new THREE.OctahedronGeometry(size, 0);
    geo.scale(0.66, 1.5, 0.66);
    geo.translate(0, size * 1.5, 0);
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
    return geo;
  });
}

/**
 * Flat annulus in the XZ plane. UV: u = angle fraction (0..1),
 * v = across the band (0 = inner edge, 1 = outer edge).
 */
export function beaconRingGeometry(radius = 1, thickness = 0.09, segments = 72): THREE.BufferGeometry {
  return cached(`ring|${radius}|${thickness}|${segments}`, () => {
    const ri = radius - thickness * 0.5;
    const ro = radius + thickness * 0.5;
    const pos: number[] = [];
    const nrm: number[] = [];
    const uvs: number[] = [];
    for (let i = 0; i < segments; i++) {
      const t0 = i / segments;
      const t1 = (i + 1) / segments;
      const a0 = t0 * TAU;
      const a1 = t1 * TAU;
      const ci0 = Math.cos(a0);
      const si0 = Math.sin(a0);
      const ci1 = Math.cos(a1);
      const si1 = Math.sin(a1);
      const A: number[] = [ri * ci0, 0, ri * si0];
      const B: number[] = [ro * ci0, 0, ro * si0];
      const C: number[] = [ro * ci1, 0, ro * si1];
      const D: number[] = [ri * ci1, 0, ri * si1];
      pos.push(...A, ...C, ...B, ...A, ...D, ...C);
      for (let k = 0; k < 6; k++) nrm.push(0, 1, 0);
      uvs.push(t0, 0, t1, 1, t0, 1, t0, 0, t1, 0, t1, 1);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.computeBoundingSphere();
    return geo;
  });
}

/** Open-ended light column for objective beacons. UV v: 0 = base, 1 = top. */
export function lightColumnGeometry(radius = 0.32, height = 6, segments = 14): THREE.BufferGeometry {
  return cached(`column|${radius}|${height}|${segments}`, () => {
    const geo = new THREE.CylinderGeometry(radius * 1.9, radius, height, segments, 1, true);
    geo.translate(0, height * 0.5, 0);
    geo.computeBoundingSphere();
    return geo;
  });
}

/** Unit quad in the XY plane, centred on the origin — the billboard primitive. */
export function billboardQuadGeometry(size = 1): THREE.BufferGeometry {
  return cached(`quad|${size}`, () => {
    const geo = new THREE.PlaneGeometry(size, size, 1, 1);
    geo.computeBoundingSphere();
    return geo;
  });
}

/** Flat unit quad lying in the XZ plane (ground decals, shadows). */
export function groundQuadGeometry(size = 1): THREE.BufferGeometry {
  return cached(`groundQuad|${size}`, () => {
    const geo = new THREE.PlaneGeometry(size, size, 1, 1);
    geo.rotateX(-Math.PI / 2);
    geo.computeBoundingSphere();
    return geo;
  });
}

/** Low-poly translucent mote used for friendly spy drones. */
export function moteGeometry(size = 1): THREE.BufferGeometry {
  return cached(`mote|${size}`, () => {
    const geo = new THREE.IcosahedronGeometry(size, 0);
    geo.scale(1, 0.72, 1);
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
    return geo;
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Fortification obelisks — three visual tiers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Low-poly fortification obelisk. Base sits on y = 0.
 *   tier 1 OUTPOST — squat plinth + short spike
 *   tier 2 BASTION — taller shaft, collar, buttress fins
 *   tier 3 CITADEL — full mast, twin collars, three fins, floating cap
 */
export function obeliskGeometry(tier: 1 | 2 | 3): THREE.BufferGeometry {
  return cached(`obelisk|${tier}`, () => {
    const parts: THREE.BufferGeometry[] = [];

    const add = (g: THREE.BufferGeometry): void => {
      if (g.index) {
        parts.push(g.toNonIndexed());
        g.dispose();
      } else {
        parts.push(g);
      }
    };

    const plinthR = 0.2 + tier * 0.055;
    const plinthH = 0.08 + tier * 0.02;
    const plinth = new THREE.CylinderGeometry(plinthR * 0.86, plinthR, plinthH, 6, 1, false);
    plinth.translate(0, plinthH * 0.5, 0);
    add(plinth);

    const shaftH = tier === 1 ? 0.4 : tier === 2 ? 0.66 : 0.98;
    const shaftTop = tier === 1 ? 0.055 : tier === 2 ? 0.062 : 0.072;
    const shaftBot = tier === 1 ? 0.13 : tier === 2 ? 0.15 : 0.175;
    const shaft = new THREE.CylinderGeometry(shaftTop, shaftBot, shaftH, 4, 1, false);
    shaft.rotateY(Math.PI / 4);
    shaft.translate(0, plinthH + shaftH * 0.5, 0);
    add(shaft);

    if (tier >= 2) {
      const collarY = plinthH + shaftH * 0.62;
      const collar = new THREE.CylinderGeometry(0.185, 0.185, 0.045, 6, 1, false);
      collar.translate(0, collarY, 0);
      add(collar);
    }
    if (tier === 3) {
      const collar2 = new THREE.CylinderGeometry(0.145, 0.145, 0.04, 6, 1, false);
      collar2.translate(0, plinthH + shaftH * 0.34, 0);
      add(collar2);
    }

    const fins = tier === 1 ? 0 : tier === 2 ? 2 : 3;
    for (let i = 0; i < fins; i++) {
      const a = (i / Math.max(1, fins)) * TAU + Math.PI / 6;
      const fin = new THREE.BoxGeometry(0.035, shaftH * 0.46, 0.12);
      fin.translate(0, plinthH + shaftH * 0.3, 0.17);
      fin.rotateY(a);
      add(fin);
    }

    const capY = plinthH + shaftH + (tier === 3 ? 0.12 : 0.045);
    const capR = tier === 1 ? 0.07 : tier === 2 ? 0.085 : 0.105;
    const cap = new THREE.OctahedronGeometry(capR, 0);
    cap.scale(1, 1.55, 1);
    cap.translate(0, capY, 0);
    add(cap);

    const merged = mergeGeometries(parts, false);
    for (const p of parts) p.dispose();
    merged.computeVertexNormals();
    merged.computeBoundingSphere();
    return merged;
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Ribbons (movement paths, territory borders, trails) — never cached
// ─────────────────────────────────────────────────────────────────────────────

export interface RibbonOptions {
  /** Per-point colour; broadcast into `aColor`. Defaults to white. */
  colors?: THREE.Color[];
  /** Taper the strip from full width at the start to `taper` at the end. */
  taper?: number;
}

const RB_A = new THREE.Vector3();
const RB_B = new THREE.Vector3();
const RB_T = new THREE.Vector3();
const RB_S = new THREE.Vector3();
const RB_UP = new THREE.Vector3(0, 1, 0);

/**
 * Builds a flat quad-strip ribbon along `points` (world space, XZ plane).
 * Attributes: position, normal (+Y), uv (u = length fraction, v = across),
 * `aDist` (cumulative world length) and `aColor`.
 * `userData.length` holds the total run length.
 */
export function buildRibbon(
  points: readonly THREE.Vector3[],
  width: number,
  opts: RibbonOptions = {},
): THREE.BufferGeometry {
  const geo = new THREE.BufferGeometry();
  const n = points.length;
  if (n < 2) {
    geo.setAttribute('position', new THREE.Float32BufferAttribute([], 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute([], 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute([], 2));
    geo.setAttribute('aDist', new THREE.Float32BufferAttribute([], 1));
    geo.setAttribute('aColor', new THREE.Float32BufferAttribute([], 3));
    geo.userData.length = 0;
    return geo;
  }

  const dists: number[] = [0];
  let total = 0;
  for (let i = 1; i < n; i++) {
    total += points[i].distanceTo(points[i - 1]);
    dists.push(total);
  }
  const safeTotal = total || 1;
  const taper = opts.taper ?? 1;

  const pos = new Float32Array(n * 2 * 3);
  const nrm = new Float32Array(n * 2 * 3);
  const uvs = new Float32Array(n * 2 * 2);
  const dst = new Float32Array(n * 2);
  const col = new Float32Array(n * 2 * 3);

  for (let i = 0; i < n; i++) {
    const p = points[i];
    RB_A.copy(points[Math.max(0, i - 1)]);
    RB_B.copy(points[Math.min(n - 1, i + 1)]);
    RB_T.subVectors(RB_B, RB_A);
    RB_T.y = 0;
    if (RB_T.lengthSq() < 1e-9) RB_T.set(0, 0, 1);
    RB_T.normalize();
    RB_S.crossVectors(RB_UP, RB_T).normalize();
    const f = dists[i] / safeTotal;
    const w = width * 0.5 * (1 - (1 - taper) * f);

    const c = opts.colors ? opts.colors[Math.min(i, opts.colors.length - 1)] : null;
    const cr = c ? c.r : 1;
    const cg = c ? c.g : 1;
    const cb = c ? c.b : 1;

    for (let s = 0; s < 2; s++) {
      const idx = i * 2 + s;
      const sign = s === 0 ? -1 : 1;
      pos[idx * 3 + 0] = p.x + RB_S.x * w * sign;
      pos[idx * 3 + 1] = p.y;
      pos[idx * 3 + 2] = p.z + RB_S.z * w * sign;
      nrm[idx * 3 + 1] = 1;
      uvs[idx * 2 + 0] = f;
      uvs[idx * 2 + 1] = s;
      dst[idx] = dists[i];
      col[idx * 3 + 0] = cr;
      col[idx * 3 + 1] = cg;
      col[idx * 3 + 2] = cb;
    }
  }

  const index: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    const a = i * 2;
    index.push(a, a + 1, a + 3, a, a + 3, a + 2);
  }

  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geo.setAttribute('aDist', new THREE.BufferAttribute(dst, 1));
  geo.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
  geo.setIndex(index);
  geo.computeBoundingSphere();
  geo.userData.length = total;
  return geo;
}

// ─────────────────────────────────────────────────────────────────────────────
// InstancedBatch — one draw call per visual family
// ─────────────────────────────────────────────────────────────────────────────

export interface BatchAttr {
  name: string;
  size: number;
  /** Optional per-component defaults used when the buffer is (re)allocated. */
  fill?: number[];
}

/**
 * Thin wrapper over InstancedMesh that owns its own cloned geometry plus a set
 * of per-instance float attributes. Callers do:
 *
 *   batch.begin();
 *   const i = batch.add(matrix);
 *   batch.set(i, 'iColor', r, g, b);
 *   batch.end();
 *
 * Capacity grows automatically (the underlying mesh is rebuilt and re-parented).
 */
export class InstancedBatch {
  mesh: THREE.InstancedMesh;
  private readonly base: THREE.BufferGeometry;
  private readonly material: THREE.Material;
  private readonly attrs: BatchAttr[];
  private readonly parent: THREE.Object3D;
  private cursor = 0;
  private capacity: number;
  private dirty = new Set<string>();
  private matrixDirty = false;
  /** Render order / layer bookkeeping copied onto rebuilt meshes. */
  renderOrder = 0;

  constructor(
    parent: THREE.Object3D,
    base: THREE.BufferGeometry,
    material: THREE.Material,
    capacity: number,
    attrs: BatchAttr[] = [],
  ) {
    this.parent = parent;
    this.base = base;
    this.material = material;
    this.attrs = attrs;
    this.capacity = Math.max(1, capacity);
    this.mesh = this.build(this.capacity);
    parent.add(this.mesh);
  }

  private build(capacity: number): THREE.InstancedMesh {
    const geo = this.base.clone();
    for (const a of this.attrs) {
      const arr = new Float32Array(capacity * a.size);
      if (a.fill) {
        for (let i = 0; i < capacity; i++) {
          for (let c = 0; c < a.size; c++) arr[i * a.size + c] = a.fill[c] ?? 0;
        }
      }
      const attr = new THREE.InstancedBufferAttribute(arr, a.size);
      attr.setUsage(THREE.DynamicDrawUsage);
      geo.setAttribute(a.name, attr);
    }
    const mesh = new THREE.InstancedMesh(geo, this.material, capacity);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    mesh.count = 0;
    mesh.renderOrder = this.renderOrder;
    return mesh;
  }

  /** Grows the batch if needed. Existing contents are discarded. */
  ensure(capacity: number): void {
    if (capacity <= this.capacity) return;
    let next = this.capacity;
    while (next < capacity) next = Math.ceil(next * 1.75) + 8;
    const old = this.mesh;
    this.capacity = next;
    this.mesh = this.build(next);
    this.mesh.renderOrder = old.renderOrder;
    this.mesh.visible = old.visible;
    this.parent.remove(old);
    old.geometry.dispose();
    old.dispose();
    this.parent.add(this.mesh);
  }

  begin(): void {
    this.cursor = 0;
    this.dirty.clear();
    this.matrixDirty = false;
  }

  /** Appends one instance; returns its index, or -1 when the batch is full. */
  add(matrix: THREE.Matrix4): number {
    if (this.cursor >= this.capacity) return -1;
    const i = this.cursor++;
    this.mesh.setMatrixAt(i, matrix);
    this.matrixDirty = true;
    return i;
  }

  set(index: number, name: string, ...values: number[]): void {
    if (index < 0) return;
    const attr = this.mesh.geometry.getAttribute(name) as THREE.InstancedBufferAttribute | undefined;
    if (!attr) return;
    const arr = attr.array as Float32Array;
    const off = index * attr.itemSize;
    for (let c = 0; c < attr.itemSize && c < values.length; c++) arr[off + c] = values[c];
    this.dirty.add(name);
  }

  end(): void {
    this.mesh.count = this.cursor;
    if (this.matrixDirty) this.mesh.instanceMatrix.needsUpdate = true;
    for (const name of this.dirty) {
      const attr = this.mesh.geometry.getAttribute(name) as THREE.InstancedBufferAttribute | undefined;
      if (attr) attr.needsUpdate = true;
    }
    this.dirty.clear();
  }

  get count(): number {
    return this.cursor;
  }

  setRenderOrder(order: number): void {
    this.renderOrder = order;
    this.mesh.renderOrder = order;
  }

  setVisible(v: boolean): void {
    this.mesh.visible = v;
  }

  dispose(): void {
    this.parent.remove(this.mesh);
    this.mesh.geometry.dispose();
    this.mesh.dispose();
  }
}
