/**
 * TERRA BELLUM — Stage: the WebGL host.
 *
 * Owns the renderer, the composer chain, the resize observer and the frame
 * loop. Scenes never touch any of that: they hand the Stage a scene + camera
 * and receive a `(dt, elapsed)` tick.
 *
 * Camera shake is applied as a POST-RENDER offset — the impulse is added to the
 * camera immediately before `composer.render()` and removed straight after, so
 * scene code (and MapControls) never sees a perturbed transform.
 */
import * as THREE from 'three';
import type { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { createConsolePost, type ConsolePost, type Quality } from './postfx';
import { setSceneCamera, updateAllMaterials } from './materials';

export type { Quality };

export interface DeviceProfile {
  quality: Quality;
  webgl2: boolean;
  /** Raw devicePixelRatio reported by the browser. */
  devicePixelRatio: number;
  /** Pixel ratio actually used for the drawing buffer. */
  maxPixelRatio: number;
  cores: number;
  memoryGb: number;
  rendererString: string;
  mobile: boolean;
  antialias: boolean;
  shadows: boolean;
}

/** Coarse GPU denylist — integrated / software / old mobile parts. */
const WEAK_GPU = /swiftshader|llvmpipe|software|mesa offscreen|adreno \(tm\) [1-5][0-9][0-9]\b|mali-[tg]?[0-6][0-9]{0,2}\b|powervr (sgx|rogue g6)|apple a([789]|10)\b|intel\(r\) hd graphics [2-5]/i;
const STRONG_GPU = /apple m[1-9]|apple a1[5-9]|rtx|radeon rx|geforce gtx 1[06-9]|adreno \(tm\) (7[0-9][0-9]|6[5-9][0-9])/i;

function readRendererString(): { gl2: boolean; renderer: string } {
  let renderer = '';
  let gl2 = false;
  try {
    const canvas = document.createElement('canvas');
    const gl = (canvas.getContext('webgl2') ??
      canvas.getContext('webgl')) as WebGLRenderingContext | null;
    if (gl) {
      gl2 = typeof WebGL2RenderingContext !== 'undefined' && gl instanceof WebGL2RenderingContext;
      const ext = gl.getExtension('WEBGL_debug_renderer_info');
      if (ext) renderer = String(gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) ?? '');
      if (!renderer) renderer = String(gl.getParameter(gl.RENDERER) ?? '');
      const lose = gl.getExtension('WEBGL_lose_context');
      lose?.loseContext();
    }
  } catch {
    /* headless / blocked — fall through to the conservative default */
  }
  return { gl2, renderer };
}

/** Inspects the device once and picks a rendering tier. */
export function detectDeviceProfile(): DeviceProfile {
  const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1;
  const cores = typeof navigator !== 'undefined' ? navigator.hardwareConcurrency || 4 : 4;
  const memoryGb =
    typeof navigator !== 'undefined'
      ? ((navigator as Navigator & { deviceMemory?: number }).deviceMemory ?? 4)
      : 4;
  const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
  const mobile = /android|iphone|ipad|ipod|mobile|silk/i.test(ua);
  const { gl2, renderer } = readRendererString();

  let score = 0;
  score += gl2 ? 2 : -2;
  score += cores >= 8 ? 2 : cores >= 6 ? 1 : cores >= 4 ? 0 : -2;
  score += memoryGb >= 8 ? 1 : memoryGb >= 4 ? 0 : -2;
  score += mobile ? -1 : 1;
  if (WEAK_GPU.test(renderer)) score -= 4;
  if (STRONG_GPU.test(renderer)) score += 3;
  if (dpr >= 3 && mobile) score -= 1;

  const quality: Quality = score >= 4 ? 'high' : score >= 1 ? 'medium' : 'low';
  const maxPixelRatio =
    quality === 'high'
      ? Math.min(dpr, 2)
      : quality === 'medium'
        ? Math.min(dpr, 1.75)
        : Math.min(dpr, 1.25);

  return {
    quality,
    webgl2: gl2,
    devicePixelRatio: dpr,
    maxPixelRatio,
    cores,
    memoryGb,
    rendererString: renderer,
    mobile,
    antialias: quality === 'high' && dpr < 2,
    shadows: false,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// SimClock — bridges compressed game time to smooth wall-clock frames
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The simulated world may run faster than real time (SIM.timeScale), and state
 * arrives in discrete pushes. SimClock estimates the ratio between game-time
 * and wall-time from successive syncs so token interpolation stays smooth
 * between them.
 */
export class SimClock {
  private simNow = 0;
  private lastSim = 0;
  private lastReal = 0;
  private rate = 1;

  /** Feed every authoritative `state.now`. */
  sync(now: number): void {
    const real = typeof performance !== 'undefined' ? performance.now() : Date.now();
    if (this.lastReal > 0) {
      const dReal = real - this.lastReal;
      const dSim = now - this.lastSim;
      if (dReal > 30 && dSim >= 0) {
        const observed = Math.min(600, dSim / dReal);
        this.rate = this.rate * 0.72 + observed * 0.28;
      }
    }
    this.lastReal = real;
    this.lastSim = now;
    // Never rewind — snap forward, ease backward.
    this.simNow = this.simNow > now ? this.simNow * 0.5 + now * 0.5 : now;
  }

  /** Advance by a real-time delta in seconds. */
  advance(dt: number): void {
    this.simNow += dt * 1000 * this.rate;
  }

  get now(): number {
    return this.simNow;
  }

  get timeScale(): number {
    return this.rate;
  }

  reset(): void {
    this.simNow = 0;
    this.lastSim = 0;
    this.lastReal = 0;
    this.rate = 1;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Stage
// ─────────────────────────────────────────────────────────────────────────────

export type FrameCallback = (dt: number, elapsed: number) => void;

const AXIS_X = new THREE.Vector3(1, 0, 0);
const AXIS_Y = new THREE.Vector3(0, 1, 0);
const AXIS_Z = new THREE.Vector3(0, 0, 1);

export class Stage {
  readonly renderer: THREE.WebGLRenderer;
  readonly composer: EffectComposer;
  readonly post: ConsolePost;
  readonly profile: DeviceProfile;
  readonly quality: Quality;
  readonly canvas: HTMLCanvasElement;

  private readonly container: HTMLElement;
  private readonly observer: ResizeObserver | null = null;
  private scene: THREE.Scene | null = null;
  private camera: THREE.PerspectiveCamera | null = null;
  private onFrame: FrameCallback | null = null;
  private rafId = 0;
  private running = false;
  private lastTime = 0;
  private elapsed = 0;
  private width = 1;
  private height = 1;

  // shake state
  private shakeAmp = 0;
  private shakeDecay = 6;
  private shakeSeed = Math.random() * 1000;
  private readonly shakeOffset = new THREE.Vector3();
  private readonly shakeApplied = new THREE.Vector3();
  private readonly camScratch = new THREE.Vector3();
  private readonly axisScratch = new THREE.Vector3();

  private disposed = false;

  constructor(container: HTMLElement) {
    this.container = container;
    this.profile = detectDeviceProfile();
    this.quality = this.profile.quality;

    this.renderer = new THREE.WebGLRenderer({
      antialias: this.profile.antialias,
      alpha: false,
      powerPreference: this.profile.quality === 'low' ? 'low-power' : 'high-performance',
      stencil: false,
      depth: true,
      preserveDrawingBuffer: false,
    });
    this.canvas = this.renderer.domElement;
    this.canvas.style.display = 'block';
    this.canvas.style.width = '100%';
    this.canvas.style.height = '100%';
    this.canvas.style.touchAction = 'none';
    this.canvas.style.outline = 'none';

    this.renderer.setPixelRatio(this.profile.maxPixelRatio);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.06;
    this.renderer.shadowMap.enabled = false;
    this.renderer.setClearColor(0x03060c, 1);
    this.renderer.info.autoReset = true;

    const rect = container.getBoundingClientRect();
    this.width = Math.max(1, Math.floor(rect.width || container.clientWidth || 1));
    this.height = Math.max(1, Math.floor(rect.height || container.clientHeight || 1));
    this.renderer.setSize(this.width, this.height, false);

    container.appendChild(this.canvas);

    this.post = createConsolePost(this.renderer, this.quality);
    this.composer = this.post.composer;
    this.post.setSize(this.width, this.height, this.profile.maxPixelRatio);

    if (typeof ResizeObserver !== 'undefined') {
      this.observer = new ResizeObserver(() => this.resize());
      this.observer.observe(container);
    }
  }

  setScene(scene: THREE.Scene, camera: THREE.PerspectiveCamera): void {
    this.scene = scene;
    this.camera = camera;
    this.post.setScene(scene, camera);
    camera.aspect = this.width / this.height;
    camera.updateProjectionMatrix();
  }

  start(onFrame: FrameCallback): void {
    this.onFrame = onFrame;
    if (this.running || this.disposed) return;
    this.running = true;
    this.lastTime = performance.now();
    const loop = (t: number): void => {
      if (!this.running) return;
      this.rafId = requestAnimationFrame(loop);
      const dt = Math.min(0.064, Math.max(0, (t - this.lastTime) / 1000));
      this.lastTime = t;
      this.elapsed += dt;
      this.tick(dt);
    };
    this.rafId = requestAnimationFrame(loop);
  }

  stop(): void {
    this.running = false;
    if (this.rafId) cancelAnimationFrame(this.rafId);
    this.rafId = 0;
  }

  private tick(dt: number): void {
    const { scene, camera } = this;
    this.onFrame?.(dt, this.elapsed);
    if (!scene || !camera) return;

    setSceneCamera(camera.getWorldPosition(this.camScratch));
    updateAllMaterials(this.elapsed);
    this.post.update(this.elapsed);

    // ── impulse shake, applied around the render only
    let shook = false;
    if (this.shakeAmp > 0.00005) {
      const t = this.elapsed;
      const s = this.shakeSeed;
      this.shakeOffset.set(
        Math.sin(t * 47.3 + s) * 0.6 + Math.sin(t * 91.7 + s * 1.7) * 0.4,
        Math.sin(t * 53.9 + s * 2.3) * 0.6 + Math.sin(t * 113.1 + s) * 0.4,
        Math.sin(t * 61.1 + s * 3.1) * 0.5,
      );
      // orient the impulse in camera space so it always reads on screen
      const amp = this.shakeAmp;
      const applied = this.shakeApplied.set(0, 0, 0);
      applied.addScaledVector(
        this.axisScratch.copy(AXIS_X).applyQuaternion(camera.quaternion),
        this.shakeOffset.x * amp,
      );
      applied.addScaledVector(
        this.axisScratch.copy(AXIS_Y).applyQuaternion(camera.quaternion),
        this.shakeOffset.y * amp,
      );
      applied.addScaledVector(
        this.axisScratch.copy(AXIS_Z).applyQuaternion(camera.quaternion),
        this.shakeOffset.z * amp * 0.35,
      );
      camera.position.add(applied);
      camera.updateMatrixWorld(true);
      this.shakeAmp *= Math.exp(-this.shakeDecay * dt);
      if (this.shakeAmp < 0.00005) this.shakeAmp = 0;
      shook = true;
    }

    this.composer.render(dt);

    if (shook) {
      camera.position.sub(this.shakeApplied);
      camera.updateMatrixWorld(true);
    }
  }

  /**
   * Adds a shake impulse.
   * @param amount peak offset in world units (see FX.shakeSmall / shakeBig)
   * @param ms     roughly how long it should take to fade out
   */
  shake(amount: number, ms = 320): void {
    this.shakeAmp = Math.max(this.shakeAmp, amount);
    this.shakeDecay = Math.max(1.5, 4200 / Math.max(60, ms));
    this.shakeSeed = Math.random() * 1000;
  }

  /** Pushes the console composite for cinematics. 1 = normal. */
  setPostStrength(x: number): void {
    this.post.setStrength(x);
  }

  resize(): void {
    if (this.disposed) return;
    const rect = this.container.getBoundingClientRect();
    const w = Math.max(1, Math.floor(rect.width || this.container.clientWidth || 1));
    const h = Math.max(1, Math.floor(rect.height || this.container.clientHeight || 1));
    if (w === this.width && h === this.height) return;
    this.width = w;
    this.height = h;
    this.renderer.setSize(w, h, false);
    this.post.setSize(w, h, this.profile.maxPixelRatio);
    if (this.camera) {
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
    }
  }

  get size(): { width: number; height: number } {
    return { width: this.width, height: this.height };
  }

  /** Live draw-call count — the GDD §13.8 budget is < 100 on the map. */
  get drawCalls(): number {
    return this.renderer.info.render.calls;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.stop();
    this.observer?.disconnect();
    this.post.dispose();
    this.scene = null;
    this.camera = null;
    this.onFrame = null;
    this.renderer.dispose();
    this.renderer.forceContextLoss();
    if (this.canvas.parentNode) this.canvas.parentNode.removeChild(this.canvas);
  }
}
