/**
 * TERRA BELLUM — the shader library.
 *
 * Every surface in the game is authored here as a THREE.ShaderMaterial so the
 * "orbital command console" look (cold holography, rim light, world-space
 * scan sweeps, dissolving fog) is consistent and cheap. Materials are shared
 * aggressively: one hex material drives thousands of instanced hexes.
 *
 * All materials carry an `update(elapsed)` hook and register themselves with
 * {@link updateAllMaterials}, which the Stage calls once per frame.
 *
 * Colour management: THREE.Color converts sRGB hex literals into the linear
 * working space, and the composer's OutputPass performs tone mapping + the
 * sRGB encode. Shaders therefore emit LINEAR values.
 */
import * as THREE from 'three';
import { PALETTE } from '../../config/visual';

// ─────────────────────────────────────────────────────────────────────────────
// Registry
// ─────────────────────────────────────────────────────────────────────────────

export interface FxMaterial extends THREE.ShaderMaterial {
  /** Advances any time-driven uniforms. `elapsed` is seconds since start. */
  update(elapsed: number): void;
}

const registry = new Set<FxMaterial>();

/**
 * Attaches an update hook to a ShaderMaterial and enrols it in the global
 * per-frame update. Disposing the material removes it from the registry.
 */
export function registerMaterial(
  material: THREE.ShaderMaterial,
  onUpdate?: (elapsed: number) => void,
): FxMaterial {
  const mat = material as FxMaterial;
  mat.update = (elapsed: number): void => {
    if (mat.uniforms.uTime) mat.uniforms.uTime.value = elapsed;
    onUpdate?.(elapsed);
  };
  const inherited = THREE.ShaderMaterial.prototype.dispose;
  mat.dispose = function disposeFx(this: FxMaterial): void {
    registry.delete(this);
    inherited.call(this);
  };
  registry.add(mat);
  return mat;
}

/** Drives every registered material. Called once per frame by the Stage. */
export function updateAllMaterials(elapsed: number): void {
  shared.uTime.value = elapsed;
  for (const mat of registry) mat.update(elapsed);
}

export function activeMaterialCount(): number {
  return registry.size;
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared lighting rig
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The single lighting definition for the map. MapScene builds matching
 * THREE.Light objects so the scene graph and the shaders agree.
 */
export const MAP_LIGHT = {
  keyDir: new THREE.Vector3(-0.42, 0.86, 0.3).normalize(),
  keyColor: 0x7fdcff,
  keyIntensity: 1.05,
  rimDir: new THREE.Vector3(0.66, 0.3, -0.68).normalize(),
  rimColor: 0xffb347,
  rimIntensity: 0.55,
  hemiSky: 0x2a4c78,
  hemiGround: 0x05080f,
  hemiIntensity: 0.55,
  /** World-space anchor for the sun flare billboards. */
  sunDistance: 140,
} as const;

/** Uniform objects shared by reference across every material in the library. */
const shared = {
  uTime: { value: 0 },
  uCamPos: { value: new THREE.Vector3() },
  uKeyDir: { value: MAP_LIGHT.keyDir.clone() },
  uKeyColor: { value: new THREE.Color(MAP_LIGHT.keyColor).multiplyScalar(MAP_LIGHT.keyIntensity) },
  uRimDir: { value: MAP_LIGHT.rimDir.clone() },
  uRimColor: { value: new THREE.Color(MAP_LIGHT.rimColor).multiplyScalar(MAP_LIGHT.rimIntensity) },
  uAmbTop: { value: new THREE.Color(MAP_LIGHT.hemiSky).multiplyScalar(0.46) },
  uAmbBottom: { value: new THREE.Color(MAP_LIGHT.hemiGround).multiplyScalar(1.4) },
  uFog: { value: new THREE.Color(PALETTE.void) },
  uFogNear: { value: 58 },
  uFogFar: { value: 210 },
};

/** Feeds the camera position to every rim-lit shader. Called once per frame. */
export function setSceneCamera(position: THREE.Vector3): void {
  shared.uCamPos.value.copy(position);
}

/** Tunes the distance fog used by the hex field and tokens. */
export function setSceneFog(color: number, near: number, far: number): void {
  shared.uFog.value.setHex(color);
  shared.uFogNear.value = near;
  shared.uFogFar.value = far;
}

function lightUniforms(): Record<string, THREE.IUniform> {
  return {
    uTime: shared.uTime,
    uCamPos: shared.uCamPos,
    uKeyDir: shared.uKeyDir,
    uKeyColor: shared.uKeyColor,
    uRimDir: shared.uRimDir,
    uRimColor: shared.uRimColor,
    uAmbTop: shared.uAmbTop,
    uAmbBottom: shared.uAmbBottom,
    uFog: shared.uFog,
    uFogNear: shared.uFogNear,
    uFogFar: shared.uFogFar,
  };
}

const LIGHT_DECL = /* glsl */ `
uniform float uTime;
uniform vec3  uCamPos;
uniform vec3  uKeyDir;
uniform vec3  uKeyColor;
uniform vec3  uRimDir;
uniform vec3  uRimColor;
uniform vec3  uAmbTop;
uniform vec3  uAmbBottom;
uniform vec3  uFog;
uniform float uFogNear;
uniform float uFogFar;
`;

// ─────────────────────────────────────────────────────────────────────────────
// Shared GLSL
// ─────────────────────────────────────────────────────────────────────────────

/** Hash / value-noise / fbm helpers reused by every shader in the game. */
export const GLSL_NOISE = /* glsl */ `
float tbHash11(float p){ p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }
float tbHash21(vec2 p){
  vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float tbHash31(vec3 p){
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
float tbNoise2(vec2 p){
  vec2 i = floor(p); vec2 f = fract(p); vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(tbHash21(i), tbHash21(i + vec2(1.0, 0.0)), u.x),
             mix(tbHash21(i + vec2(0.0, 1.0)), tbHash21(i + vec2(1.0, 1.0)), u.x), u.y);
}
float tbNoise3(vec3 p){
  vec3 i = floor(p); vec3 f = fract(p); vec3 u = f * f * (3.0 - 2.0 * f);
  float n000 = tbHash31(i);
  float n100 = tbHash31(i + vec3(1.0, 0.0, 0.0));
  float n010 = tbHash31(i + vec3(0.0, 1.0, 0.0));
  float n110 = tbHash31(i + vec3(1.0, 1.0, 0.0));
  float n001 = tbHash31(i + vec3(0.0, 0.0, 1.0));
  float n101 = tbHash31(i + vec3(1.0, 0.0, 1.0));
  float n011 = tbHash31(i + vec3(0.0, 1.0, 1.0));
  float n111 = tbHash31(i + vec3(1.0, 1.0, 1.0));
  return mix(mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),
             mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y), u.z);
}
float tbFbm2(vec2 p){
  float v = 0.0; float a = 0.5;
  for (int i = 0; i < 5; i++) { v += a * tbNoise2(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return v;
}
float tbFbm3(vec3 p){
  float v = 0.0; float a = 0.5;
  for (int i = 0; i < 5; i++) { v += a * tbNoise3(p); p = p * 2.02 + 11.3; a *= 0.5; }
  return v;
}
/** Hex distance in local hex space; 1.0 exactly on the pointy-top boundary. */
float tbHexDist(vec2 p){ return max(abs(p.y), abs(p.y) * 0.5 + abs(p.x) * 0.8660254); }
`;

/** Camera-facing billboard expansion shared by every sprite-ish material. */
const GLSL_BILLBOARD = /* glsl */ `
vec4 tbBillboard(mat4 im, vec2 quad, vec2 size) {
  vec4 world = modelMatrix * im * vec4(0.0, 0.0, 0.0, 1.0);
  vec4 mv = viewMatrix * world;
  mv.xy += quad * size;
  return projectionMatrix * mv;
}
`;

const GLSL_INSTANCE_MATRIX = /* glsl */ `
mat4 tbInstanceMatrix() {
  #ifdef USE_INSTANCING
    return instanceMatrix;
  #else
    return mat4(1.0);
  #endif
}
`;

// ─────────────────────────────────────────────────────────────────────────────
// Hex field material
// ─────────────────────────────────────────────────────────────────────────────

const HEX_VERT = /* glsl */ `
${GLSL_INSTANCE_MATRIX}

attribute float aFace;
attribute vec3  iColor;
attribute vec3  iOwner;
attribute vec4  iState;
attribute float iSeed;

varying vec3  vTerrain;
varying vec3  vOwner;
varying vec4  vState;
varying float vSeed;
varying float vGas;
varying float vFace;
varying vec2  vHexUv;
varying vec3  vWorld;
varying vec3  vNrm;

void main() {
  mat4 im = tbInstanceMatrix();
  float sy = max(length(im[1].xyz), 0.0001);

  vec4 world = modelMatrix * im * vec4(position, 1.0);
  vWorld = world.xyz;

  // Instances only carry translation + non-uniform Y scale, so the normal is
  // corrected analytically rather than with a full inverse-transpose.
  vec3 n = normalize(vec3(normal.x, normal.y / sy, normal.z));
  vNrm = normalize((modelMatrix * vec4(n, 0.0)).xyz);

  vHexUv = uv;
  vFace = aFace;
  vTerrain = iColor;
  vOwner = iOwner;
  vState = iState;
  vGas = step(1.5, iSeed);
  vSeed = fract(iSeed);

  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

const HEX_FRAG = /* glsl */ `
precision highp float;
${LIGHT_DECL}
uniform vec3  uNeutral;
uniform float uStrength;
uniform float uSweepSpeed;

varying vec3  vTerrain;
varying vec3  vOwner;
varying vec4  vState;
varying float vSeed;
varying float vGas;
varying float vFace;
varying vec2  vHexUv;
varying vec3  vWorld;
varying vec3  vNrm;

${GLSL_NOISE}

void main() {
  vec3 N = normalize(vNrm);
  vec3 V = normalize(uCamPos - vWorld);

  float topM  = step(0.75, vFace);          // flat top only
  float faceM = step(0.25, vFace);          // top + bevel

  float owned  = vState.x;
  float fort   = vState.y;
  float cap    = clamp(vState.z, 0.0, 1.0);
  float locked = clamp(vState.w, 0.0, 1.0);

  // ── base plate ────────────────────────────────────────────────────────────
  vec3 albedo = vTerrain * mix(0.30, 1.0, topM);
  albedo *= 0.86 + 0.30 * vSeed;
  float micro = tbNoise2(vWorld.xz * 5.5 + vSeed * 41.0);
  albedo *= 1.0 + 0.16 * (micro - 0.5) * topM;

  vec3 K = normalize(uKeyDir);
  vec3 R = normalize(uRimDir);
  float ndl = max(dot(N, K), 0.0);
  float ndr = max(dot(N, R), 0.0);
  vec3 amb = mix(uAmbBottom, uAmbTop, N.y * 0.5 + 0.5);

  vec3 col = albedo * amb;
  col += albedo * uKeyColor * ndl * 0.62;
  col += albedo * uRimColor * ndr * 0.22;

  // brushed-metal specular
  vec3 H = normalize(K + V);
  float spec = pow(max(dot(N, H), 0.0), 58.0);
  col += uKeyColor * spec * (0.035 + 0.10 * topM);

  // ── fresnel rim, tinted by the owning guild ───────────────────────────────
  // Kept deliberately modest: the field is thousands of instances and the
  // bloom pass sums all of them, so a "pretty" single-hex value floods.
  float fres = pow(1.0 - max(dot(N, V), 0.0), 2.6);
  vec3 rimCol = mix(uNeutral, vOwner, owned);
  col += rimCol * fres * (0.05 + 0.17 * owned) * uStrength;

  // ── slow holographic sweep across the whole field, in world space ─────────
  float sweepPhase = (vWorld.x * 0.105 + vWorld.z * 0.185) - uTime * uSweepSpeed;
  float sweep = smoothstep(0.982, 1.0, sin(sweepPhase));
  col += vec3(0.16, 0.62, 0.92) * sweep * 0.20 * uStrength;
  col *= 1.0 + 0.035 * (0.5 + 0.5 * sin(vWorld.z * 7.5 - uTime * 0.85));

  // ── local hex coordinates (top face + bevel) ──────────────────────────────
  vec2 p = vHexUv * 2.0 - 1.0;
  float hd = tbHexDist(p);
  float angN = atan(p.y, p.x) * 0.15915494 + 0.5;

  // rim band wrapping the top edge onto the bevel
  float band = smoothstep(0.80, 0.90, hd) * (1.0 - smoothstep(1.04, 1.18, hd));
  band *= faceM;

  // ── animated edge trace on owned hexes ────────────────────────────────────
  float travel = fract(angN - uTime * 0.10 + vSeed);
  float head = pow(smoothstep(0.78, 1.0, travel), 2.0);
  col += vOwner * band * owned * (0.09 + 0.62 * head) * uStrength;

  // ── fortification tier ring ───────────────────────────────────────────────
  float fRing = smoothstep(0.29, 0.335, hd) * (1.0 - smoothstep(0.40, 0.45, hd));
  col += vOwner * fRing * topM * step(0.5, fort) * (0.06 + 0.06 * fort);

  // ── rotating radial capture wipe ──────────────────────────────────────────
  float capOn = step(0.002, cap);
  float wipe = fract(angN + uTime * 0.075);
  float inside = step(wipe, cap);
  float edge = inside * smoothstep(cap - 0.05, cap, wipe);
  vec3 capCol = mix(vec3(1.0, 0.62, 0.20), vOwner, 0.4);
  col += capCol * capOn * (
      inside * faceM * 0.10 * (0.6 + 0.4 * sin(uTime * 5.2))
    + edge   * faceM * 0.62
    + band   * 0.22
  );

  // ── volatile gas vent pulse ───────────────────────────────────────────────
  float gp = 0.5 + 0.5 * sin(uTime * 1.35 + vSeed * 25.0);
  float inner = 1.0 - smoothstep(0.05, 0.80, hd);
  col += vec3(0.18, 1.0, 0.76) * vGas * topM * inner * (0.035 + 0.09 * gp);

  // ── locked sector: desaturate, fog, dissolve, ghost grid ──────────────────
  if (locked > 0.002) {
    float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
    vec3 dead = mix(col, vec3(lum) * 0.65, 0.92);
    float nz = tbFbm2(vWorld.xz * 0.55 + uTime * 0.018);
    float diss = smoothstep(0.32, 0.72, nz + 0.18 * sin(uTime * 0.45 + vSeed * 33.0));
    dead = mix(dead, vec3(0.026, 0.038, 0.066), 0.42 + 0.44 * diss);
    vec2 g = abs(fract(vWorld.xz * 1.05) - 0.5);
    float grid = 1.0 - smoothstep(0.0, 0.05, min(g.x, g.y));
    dead += vec3(0.08, 0.26, 0.42) * grid * topM * (0.42 - 0.34 * diss);
    dead += vec3(0.08, 0.26, 0.42) * band * 0.30;
    col = mix(col, dead, locked);
  }

  // ── depth haze into the void ──────────────────────────────────────────────
  float dist = length(uCamPos - vWorld);
  col = mix(col, uFog, smoothstep(uFogNear, uFogFar, dist));

  gl_FragColor = vec4(col, 1.0);
}
`;

/**
 * Instanced hex-field material.
 *
 * Required per-instance attributes:
 *   `iColor` vec3  terrain tint (linear)
 *   `iOwner` vec3  owning guild colour (linear)
 *   `iState` vec4  (ownedFlag, fortLevel, captureProgress 0..1, lockedFlag)
 *   `iSeed`  float fractional part = per-hex random seed, +2.0 marks a gas field
 * plus the geometry attribute `aFace` supplied by {@link hexPrismGeometry}.
 */
export function makeHexMaterial(): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      ...lightUniforms(),
      uNeutral: { value: new THREE.Color(PALETTE.edge).multiplyScalar(1.6) },
      uStrength: { value: 1 },
      uSweepSpeed: { value: 0.42 },
    },
    vertexShader: HEX_VERT,
    fragmentShader: HEX_FRAG,
    side: THREE.FrontSide,
    transparent: false,
  });
  mat.name = 'tb.hex';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Energy curtain (sector boundaries)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Additive vertical light curtain. Geometry must supply `uv` (v = 0 at the
 * base, 1 at the top), an `aIntensity` float so individual sectors can pulse on
 * their own countdown, and an `aTint` vec3. Both extra attributes work either
 * per-vertex (merged mesh) or per-instance (InstancedBatch).
 */
export function makeEnergyFieldMaterial(color: number): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uColor: { value: new THREE.Color(color) },
      uOpacity: { value: 1 },
      uScroll: { value: 0.34 },
      uHeightFade: { value: 0.9 },
    },
    vertexShader: /* glsl */ `
      ${GLSL_INSTANCE_MATRIX}
      attribute float aIntensity;
      attribute vec3 aTint;
      varying vec2 vUvC;
      varying float vI;
      varying vec3 vTint;
      varying vec3 vWorld;
      void main() {
        vUvC = uv;
        vI = aIntensity;
        vTint = aTint;
        vec4 world = modelMatrix * tbInstanceMatrix() * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uOpacity;
      uniform float uScroll;
      uniform float uHeightFade;
      varying vec2 vUvC;
      varying float vI;
      varying vec3 vTint;
      varying vec3 vWorld;
      ${GLSL_NOISE}
      void main() {
        float top = 1.0 - smoothstep(0.05, uHeightFade, vUvC.y);
        float n1 = tbFbm2(vec2(vUvC.x * 7.0, vUvC.y * 2.2 - uTime * uScroll));
        float n2 = tbNoise2(vec2(vUvC.x * 21.0 + 5.0, vUvC.y * 5.0 - uTime * uScroll * 1.9));
        float stripes = 0.62 + 0.38 * sin(vUvC.x * 220.0 + uTime * 1.4);
        float base = smoothstep(0.0, 0.10, vUvC.y);
        float a = top * (0.30 + 0.70 * n1) * (0.55 + 0.60 * n2) * stripes;
        a *= mix(0.35, 1.0, base);
        a *= uOpacity * vI * (0.78 + 0.22 * sin(uTime * 1.9 + vWorld.x * 0.2));
        if (a <= 0.002) discard;
        vec3 c = uColor * vTint * (1.0 + n1 * 0.85 + top * 0.5);
        gl_FragColor = vec4(c, a);
      }
    `,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  mat.name = 'tb.energy';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Holographic line / ribbon
// ─────────────────────────────────────────────────────────────────────────────

export interface HoloLineOptions {
  opacity?: number;
  dash?: boolean;
  dashSize?: number;
  gapSize?: number;
  /** How fast the dash pattern crawls, world units/second. */
  dashSpeed?: number;
  /** Width of the travelling highlight, world units. */
  headWidth?: number;
}

/**
 * Additive, softly pulsing ribbon material for territory borders and movement
 * paths. Geometry (see `buildRibbon`) must supply `uv` (v across the strip),
 * `aDist` (cumulative world length) and `aColor`.
 */
export function makeHoloLineMaterial(color: number, opts: HoloLineOptions = {}): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uColor: { value: new THREE.Color(color) },
      uOpacity: { value: opts.opacity ?? 0.9 },
      uDash: { value: opts.dash ? 1 : 0 },
      uDashSize: { value: opts.dashSize ?? 0.42 },
      uGapSize: { value: opts.gapSize ?? 0.3 },
      uDashSpeed: { value: opts.dashSpeed ?? 1.1 },
      uHead: { value: -999 },
      uHeadWidth: { value: opts.headWidth ?? 0.55 },
    },
    vertexShader: /* glsl */ `
      attribute float aDist;
      attribute vec3 aColor;
      varying float vDist;
      varying vec3 vCol;
      varying vec2 vUvC;
      void main() {
        vDist = aDist;
        vCol = aColor;
        vUvC = uv;
        vec4 world = modelMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uOpacity;
      uniform float uDash;
      uniform float uDashSize;
      uniform float uGapSize;
      uniform float uDashSpeed;
      uniform float uHead;
      uniform float uHeadWidth;
      varying float vDist;
      varying vec3 vCol;
      varying vec2 vUvC;
      void main() {
        float across = abs(vUvC.y * 2.0 - 1.0);
        float core = pow(1.0 - clamp(across, 0.0, 1.0), 1.7);
        float dashOn = 1.0;
        if (uDash > 0.5) {
          float period = uDashSize + uGapSize;
          float cyc = mod(vDist - uTime * uDashSpeed, period);
          dashOn = 1.0 - smoothstep(uDashSize, uDashSize + 0.07, cyc);
        }
        float hd = (vDist - uHead) / max(uHeadWidth, 0.001);
        float head = exp(-hd * hd);
        float pulse = 0.70 + 0.30 * sin(uTime * 3.1 - vDist * 1.6);
        float a = uOpacity * core * dashOn * pulse + head * core * 1.35;
        if (a <= 0.002) discard;
        vec3 c = uColor * vCol * (0.75 + 0.85 * core + head * 2.4);
        gl_FragColor = vec4(c, a);
      }
    `,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  mat.name = 'tb.holoLine';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Token material (army chevrons, obelisks, drone motes, intel ghosts)
// ─────────────────────────────────────────────────────────────────────────────

export interface TokenMaterialOptions {
  /** Base hull darkness. */
  hull?: number;
  /** Emissive trim multiplier. */
  emissive?: number;
  translucent?: boolean;
  /** Draw as an unlit additive ghost (used for "last seen" intel). */
  ghost?: boolean;
}

/**
 * Rim-lit, emissive-trimmed token material.
 * Per-instance attributes: `iColor` vec3, `iAux` vec3
 *   (x = alpha, y = hostile pulse 0..1, z = emissive boost).
 */
export function makeTokenMaterial(color: number, opts: TokenMaterialOptions = {}): FxMaterial {
  const ghost = opts.ghost === true;
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      ...lightUniforms(),
      uColor: { value: new THREE.Color(color) },
      uHull: { value: new THREE.Color(PALETTE.plate).multiplyScalar(opts.hull ?? 1) },
      uEmissive: { value: opts.emissive ?? 1 },
      uGhost: { value: ghost ? 1 : 0 },
    },
    vertexShader: /* glsl */ `
      ${GLSL_INSTANCE_MATRIX}
      attribute vec3 iColor;
      attribute vec3 iAux;
      varying vec3 vNrm;
      varying vec3 vWorld;
      varying vec3 vCol;
      varying vec3 vAux;
      void main() {
        mat4 im = tbInstanceMatrix();
        vec4 world = modelMatrix * im * vec4(position, 1.0);
        vWorld = world.xyz;
        vNrm = normalize((modelMatrix * im * vec4(normal, 0.0)).xyz);
        vCol = iColor;
        vAux = iAux;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      ${LIGHT_DECL}
      uniform vec3 uColor;
      uniform vec3 uHull;
      uniform float uEmissive;
      uniform float uGhost;
      varying vec3 vNrm;
      varying vec3 vWorld;
      varying vec3 vCol;
      varying vec3 vAux;
      ${GLSL_NOISE}
      void main() {
        vec3 N = normalize(vNrm);
        vec3 V = normalize(uCamPos - vWorld);
        vec3 tint = uColor * vCol;
        float alpha = vAux.x;
        float hostile = vAux.y;
        float boost = vAux.z;

        float fres = pow(1.0 - max(dot(N, V), 0.0), 2.1);
        float ndl = max(dot(N, normalize(uKeyDir)), 0.0);
        float ndr = max(dot(N, normalize(uRimDir)), 0.0);

        // The hull carries a fraction of the guild tint so a token reads in
        // its owner's colour even on the shadow side.
        vec3 hull = uHull + tint * 0.14 * uEmissive;
        vec3 col = hull * (0.30 + 0.70 * ndl) + hull * uAmbTop * 0.8;
        col += hull * uRimColor * ndr * 0.45;
        col += tint * fres * (0.55 + 0.45 * boost) * uEmissive;

        // emissive trim on the upward-facing panels
        float top = smoothstep(0.45, 0.94, N.y);
        col += tint * top * (0.26 + 0.34 * boost) * uEmissive;

        // scan wash so tokens read as projections
        float scan = 0.5 + 0.5 * sin(vWorld.y * 26.0 - uTime * 3.2);
        col += tint * scan * 0.07 * uEmissive;

        // hostile threat pulse
        col += tint * hostile * fres * (0.30 + 0.30 * sin(uTime * 4.6 + vWorld.x));

        if (uGhost > 0.5) {
          float wire = 1.0 - smoothstep(0.0, 0.55, abs(dot(N, V)));
          col = tint * (0.35 + 1.5 * wire);
          alpha *= 0.28 + 0.72 * wire;
        }

        float dist = length(uCamPos - vWorld);
        col = mix(col, uFog, smoothstep(uFogNear, uFogFar, dist) * (1.0 - uGhost));

        gl_FragColor = vec4(col, alpha);
      }
    `,
    transparent: opts.translucent === true || ghost,
    blending: ghost ? THREE.AdditiveBlending : THREE.NormalBlending,
    depthWrite: !(opts.translucent === true || ghost),
    side: THREE.FrontSide,
  });
  mat.name = ghost ? 'tb.tokenGhost' : 'tb.token';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Glow sprites (beacons, pings, plumes, auras)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Additive camera-facing radial sprite. Always used through an InstancedMesh.
 * Per-instance attributes: `iColor` vec3, `iAux` vec3 (x = world size,
 * y = alpha, z = twinkle phase 0..1).
 */
export function makeGlowSpriteMaterial(color: number, softness = 2.4): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uColor: { value: new THREE.Color(color) },
      uSoft: { value: softness },
      uOpacity: { value: 1 },
      uCore: { value: 0.9 },
    },
    vertexShader: /* glsl */ `
      ${GLSL_INSTANCE_MATRIX}
      ${GLSL_BILLBOARD}
      attribute vec3 iColor;
      attribute vec3 iAux;
      varying vec2 vQ;
      varying vec3 vCol;
      varying float vA;
      varying float vPhase;
      void main() {
        mat4 im = tbInstanceMatrix();
        vQ = uv * 2.0 - 1.0;
        vCol = iColor;
        vA = iAux.y;
        vPhase = iAux.z;
        gl_Position = tbBillboard(im, position.xy, vec2(iAux.x));
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uSoft;
      uniform float uOpacity;
      uniform float uCore;
      varying vec2 vQ;
      varying vec3 vCol;
      varying float vA;
      varying float vPhase;
      void main() {
        float d = length(vQ);
        if (d > 1.0) discard;
        float falloff = pow(max(0.0, 1.0 - d), uSoft);
        float core = pow(max(0.0, 1.0 - d), 12.0) * uCore;
        float tw = 0.82 + 0.18 * sin(uTime * 2.3 + vPhase * 6.2831853);
        float a = (falloff + core) * vA * uOpacity * tw;
        if (a <= 0.002) discard;
        gl_FragColor = vec4(uColor * vCol * (1.0 + core * 2.0), a);
      }
    `,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    depthTest: true,
    side: THREE.DoubleSide,
  });
  mat.name = 'tb.glow';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Ground decals (shadows, shockwave rings, selection rings)
// ─────────────────────────────────────────────────────────────────────────────

export interface DecalOptions {
  /** 'disc' expects a flat quad, 'ring' expects `beaconRingGeometry`. */
  mode?: 'disc' | 'ring';
  softness?: number;
  additive?: boolean;
  opacity?: number;
}

/**
 * Flat, ground-hugging decal drawn with the plain instance transform (no
 * billboarding), used for army shadows, selection rings and ping shockwaves.
 * Per-instance attributes: `iColor` vec3, `iAux` vec3
 *   (x = alpha, y = phase, z = sweep 0..1 for radial wipes).
 */
export function makeDecalMaterial(color: number, opts: DecalOptions = {}): FxMaterial {
  const ring = opts.mode === 'ring';
  const additive = opts.additive !== false;
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uColor: { value: new THREE.Color(color) },
      uSoft: { value: opts.softness ?? 2.2 },
      uOpacity: { value: opts.opacity ?? 1 },
      uRing: { value: ring ? 1 : 0 },
    },
    vertexShader: /* glsl */ `
      ${GLSL_INSTANCE_MATRIX}
      attribute vec3 iColor;
      attribute vec3 iAux;
      varying vec2 vUvC;
      varying vec3 vCol;
      varying vec3 vAux;
      void main() {
        mat4 im = tbInstanceMatrix();
        vUvC = uv;
        vCol = iColor;
        vAux = iAux;
        vec4 world = modelMatrix * im * vec4(position, 1.0);
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform float uTime;
      uniform vec3 uColor;
      uniform float uSoft;
      uniform float uOpacity;
      uniform float uRing;
      varying vec2 vUvC;
      varying vec3 vCol;
      varying vec3 vAux;
      void main() {
        vec2 p = vUvC * 2.0 - 1.0;
        float disc = pow(max(0.0, 1.0 - length(p)), uSoft);
        float band = 1.0 - abs(vUvC.y * 2.0 - 1.0);
        float ringM = pow(clamp(band, 0.0, 1.0), 0.85);
        float shape = mix(disc, ringM, uRing);

        // optional radial wipe — ring geometry maps u to the angle fraction
        float sweep = vAux.z;
        float gate = 1.0;
        if (uRing > 0.5 && sweep > 0.001) {
          gate = step(vUvC.x, sweep) * (0.55 + 0.45 * smoothstep(sweep - 0.09, sweep, vUvC.x));
        }

        float flick = 0.86 + 0.14 * sin(uTime * 4.0 + vAux.y * 6.2831853);
        float a = shape * vAux.x * uOpacity * gate * flick;
        if (a <= 0.002) discard;
        gl_FragColor = vec4(uColor * vCol * (0.8 + shape * 1.5), a);
      }
    `,
    transparent: true,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    depthWrite: false,
    depthTest: true,
    side: THREE.DoubleSide,
  });
  mat.name = ring ? 'tb.decalRing' : 'tb.decalDisc';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Atlas billboards (text labels, glyphs, count badges)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Instanced, camera-facing textured billboard reading a sub-rectangle of a
 * shared atlas — one draw call for every label on screen.
 * Per-instance attributes: `iRect` vec4 (u0, v0, du, dv), `iAux` vec3
 * (x = world width, y = world height, z = alpha), `iColor` vec3.
 */
export function makeAtlasBillboardMaterial(map: THREE.Texture, depthTest = false): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uMap: { value: map },
      uOpacity: { value: 1 },
    },
    vertexShader: /* glsl */ `
      ${GLSL_INSTANCE_MATRIX}
      ${GLSL_BILLBOARD}
      attribute vec4 iRect;
      attribute vec3 iAux;
      attribute vec3 iColor;
      varying vec2 vUvT;
      varying float vA;
      varying vec3 vCol;
      void main() {
        mat4 im = tbInstanceMatrix();
        vUvT = iRect.xy + uv * iRect.zw;
        vA = iAux.z;
        vCol = iColor;
        gl_Position = tbBillboard(im, position.xy, iAux.xy);
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform sampler2D uMap;
      uniform float uOpacity;
      varying vec2 vUvT;
      varying float vA;
      varying vec3 vCol;
      void main() {
        vec4 t = texture2D(uMap, vUvT);
        float a = t.a * vA * uOpacity;
        if (a <= 0.004) discard;
        gl_FragColor = vec4(t.rgb * vCol, a);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest,
    side: THREE.DoubleSide,
  });
  mat.name = 'tb.atlas';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Ground plane beneath the hex field
// ─────────────────────────────────────────────────────────────────────────────

/** Deep-space deck plate the hex field floats on: radial grid + soft horizon. */
export function makeGroundMaterial(): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      ...lightUniforms(),
      uGrid: { value: new THREE.Color(PALETTE.cyanDeep).multiplyScalar(0.55) },
      uBase: { value: new THREE.Color(PALETTE.abyss) },
      uRadius: { value: 100 },
    },
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      void main() {
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      ${LIGHT_DECL}
      uniform vec3 uGrid;
      uniform vec3 uBase;
      uniform float uRadius;
      varying vec3 vWorld;
      ${GLSL_NOISE}
      void main() {
        float r = length(vWorld.xz);
        float fade = 1.0 - smoothstep(uRadius * 0.35, uRadius, r);
        vec2 g = abs(fract(vWorld.xz * 0.2887) - 0.5);
        float lines = 1.0 - smoothstep(0.0, 0.02, min(g.x, g.y));
        float rings = 1.0 - smoothstep(0.0, 0.018, abs(fract(r * 0.08 - uTime * 0.02) - 0.5) );
        float n = tbFbm2(vWorld.xz * 0.05 + 3.7);
        vec3 col = uBase * (0.5 + 0.9 * n);
        col += uGrid * lines * 0.5 * fade;
        col += uGrid * rings * 0.35 * fade;
        col = mix(uFog, col, fade);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
    side: THREE.FrontSide,
    depthWrite: true,
  });
  mat.name = 'tb.ground';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Rising particle columns (gas vents)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GPU-animated point cloud for gas plumes. Geometry attributes:
 * `position` (vent base), `aPhase` float, `aSpeed` float, `aSize` float,
 * `aSpread` vec2.
 */
export function makeVentParticleMaterial(color: number, pixelRatio = 1): FxMaterial {
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: shared.uTime,
      uColor: { value: new THREE.Color(color) },
      uPixelRatio: { value: pixelRatio },
      uHeight: { value: 2.2 },
      uOpacity: { value: 0.42 },
    },
    vertexShader: /* glsl */ `
      attribute float aPhase;
      attribute float aSpeed;
      attribute float aSize;
      attribute vec2 aSpread;
      uniform float uTime;
      uniform float uPixelRatio;
      uniform float uHeight;
      varying float vLife;
      void main() {
        float life = fract(aPhase + uTime * aSpeed * 0.14);
        vLife = life;
        vec3 p = position;
        p.y += life * uHeight;
        p.x += aSpread.x * life * 1.6 + sin(uTime * 0.8 + aPhase * 30.0) * 0.05 * life;
        p.z += aSpread.y * life * 1.6 + cos(uTime * 0.7 + aPhase * 21.0) * 0.05 * life;
        vec4 mv = viewMatrix * modelMatrix * vec4(p, 1.0);
        gl_PointSize = aSize * uPixelRatio * (18.0 / max(0.1, -mv.z)) * (0.4 + life);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform vec3 uColor;
      uniform float uOpacity;
      varying float vLife;
      void main() {
        vec2 q = gl_PointCoord * 2.0 - 1.0;
        float d = dot(q, q);
        if (d > 1.0) discard;
        float a = (1.0 - d) * (1.0 - d);
        a *= smoothstep(0.0, 0.15, vLife) * (1.0 - smoothstep(0.55, 1.0, vLife));
        gl_FragColor = vec4(uColor * (1.4 - vLife * 0.6), a * uOpacity);
      }
    `,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  mat.name = 'tb.vent';
  return registerMaterial(mat);
}

// ─────────────────────────────────────────────────────────────────────────────
// Disposal
// ─────────────────────────────────────────────────────────────────────────────

/** Disposes every registered material. Full-teardown escape hatch. */
export function disposeAllMaterials(): void {
  for (const mat of Array.from(registry)) mat.dispose();
  registry.clear();
}
