/**
 * TERRA BELLUM — the console composite.
 *
 * Chain:  RenderPass → UnrealBloomPass → ConsoleComposite → OutputPass
 *
 * ConsoleComposite is one fragment shader that layers, in this order:
 *   1. chromatic aberration scaled from the screen centre
 *   2. a faint cyan hologram lift in the shadows (CRT phosphor bleed)
 *   3. rolling horizontal scanlines
 *   4. animated film grain
 *   5. a soft vignette + corner bracket darkening
 *
 * Everything before OutputPass is linear HDR; OutputPass applies the renderer's
 * tone mapping and the sRGB encode.
 */
import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { POST } from '../../config/visual';

export type Quality = 'high' | 'medium' | 'low';

const CONSOLE_COMPOSITE_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const CONSOLE_COMPOSITE_FRAG = /* glsl */ `
precision highp float;

uniform sampler2D tDiffuse;
uniform vec2  uResolution;
uniform float uTime;
uniform float uStrength;
uniform float uChromatic;
uniform float uScanline;
uniform float uGrain;
uniform float uVignette;
uniform vec3  uHoloTint;
uniform float uHoloLift;

varying vec2 vUv;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 uv = vUv;
  vec2 centred = uv - 0.5;
  float r2 = dot(centred, centred);

  // ── 1. chromatic aberration, zero at the centre, strongest at the corners
  float ca = uChromatic * uStrength * (0.35 + 2.6 * r2);
  vec2 dir = centred * 2.0;
  vec3 col;
  col.r = texture2D(tDiffuse, uv + dir * ca).r;
  col.g = texture2D(tDiffuse, uv).g;
  col.b = texture2D(tDiffuse, uv - dir * ca).b;

  // ── 2. hologram lift: shadows drift toward cold cyan.
  //      The buffer is still LINEAR here, so this stays deliberately tiny —
  //      a few thousandths already reads as a visible phosphor bleed.
  float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
  float shadow = 1.0 - smoothstep(0.0, 0.08, lum);
  col += uHoloTint * shadow * uHoloLift * uStrength;

  // ── 3. rolling scanlines (two frequencies so they never look like a moire)
  float lines = sin((uv.y * uResolution.y * 0.85) - uTime * 14.0);
  float roll = sin((uv.y * 2.4) - uTime * 0.35);
  float scan = (lines * 0.5 + 0.5) * (0.75 + 0.25 * (roll * 0.5 + 0.5));
  col *= 1.0 - uScanline * uStrength * scan;

  // a single bright sweep bar crawling down the panel
  float bar = smoothstep(0.986, 1.0, sin(uv.y * 3.0 - uTime * 0.22));
  col += uHoloTint * bar * 0.012 * uStrength;

  // ── 4. animated film grain
  float g = hash12(uv * uResolution + fract(uTime) * 977.0);
  col += (g - 0.5) * uGrain * uStrength;

  // ── 5. vignette + corner darkening
  // (written as 1 - smoothstep(lo, hi, x); a descending smoothstep is
  //  undefined in the GLSL ES spec even though most drivers tolerate it)
  float vig = 1.0 - smoothstep(0.18, 0.90, r2 * 2.2);
  col *= mix(1.0, vig, uVignette * uStrength);

  // faint edge falloff so the panel reads as glass behind a bezel
  float edge = smoothstep(0.0, 0.09, uv.x) * (1.0 - smoothstep(0.91, 1.0, uv.x))
             * smoothstep(0.0, 0.06, uv.y) * (1.0 - smoothstep(0.94, 1.0, uv.y));
  col *= mix(1.0, 0.72 + 0.28 * edge, 0.5 * uStrength);

  gl_FragColor = vec4(max(col, vec3(0.0)), 1.0);
}
`;

export interface ConsolePost {
  readonly composer: EffectComposer;
  readonly renderPass: RenderPass;
  readonly bloom: UnrealBloomPass;
  readonly composite: ShaderPass;
  readonly output: OutputPass;
  /** Points the chain at a different scene/camera without rebuilding it. */
  setScene(scene: THREE.Scene, camera: THREE.Camera): void;
  /** 0 = clean feed, 1 = normal, >1 = cinematic push. */
  setStrength(x: number): void;
  strength: number;
  setSize(width: number, height: number, pixelRatio: number): void;
  update(elapsed: number): void;
  dispose(): void;
}

/**
 * Builds the composer chain. The RenderPass starts on a throwaway scene so the
 * Stage can expose `composer` as readonly and swap scenes later.
 */
export function createConsolePost(renderer: THREE.WebGLRenderer, quality: Quality): ConsolePost {
  const size = new THREE.Vector2();
  renderer.getSize(size);
  const w = Math.max(1, size.x);
  const h = Math.max(1, size.y);

  const composer = new EffectComposer(renderer);
  composer.setPixelRatio(renderer.getPixelRatio());
  composer.setSize(w, h);

  const placeholderScene = new THREE.Scene();
  const placeholderCamera = new THREE.PerspectiveCamera();
  const renderPass = new RenderPass(placeholderScene, placeholderCamera);
  composer.addPass(renderPass);

  const low = quality === 'low';
  const med = quality === 'medium';
  const bloomStrength = low
    ? POST.lowBloomStrength
    : med
      ? (POST.bloomStrength + POST.lowBloomStrength) * 0.5
      : POST.bloomStrength;
  const bloomRadius = low ? POST.bloomRadius * 0.7 : POST.bloomRadius;

  const bloom = new UnrealBloomPass(
    new THREE.Vector2(w, h),
    bloomStrength,
    bloomRadius,
    POST.bloomThreshold,
  );
  composer.addPass(bloom);

  const qualityScale = low ? 0.55 : med ? 0.8 : 1;

  const composite = new ShaderPass({
    uniforms: {
      tDiffuse: { value: null },
      uResolution: { value: new THREE.Vector2(w, h) },
      uTime: { value: 0 },
      uStrength: { value: 1 },
      uChromatic: { value: POST.chromatic * qualityScale },
      uScanline: { value: POST.scanlineIntensity * qualityScale },
      uGrain: { value: POST.grain * qualityScale },
      uVignette: { value: POST.vignette },
      uHoloTint: { value: new THREE.Color(0x4de3ff) },
      uHoloLift: { value: low ? 0.006 : 0.011 },
    },
    vertexShader: CONSOLE_COMPOSITE_VERT,
    fragmentShader: CONSOLE_COMPOSITE_FRAG,
  });
  composite.material.name = 'tb.consoleComposite';
  composer.addPass(composite);

  const output = new OutputPass();
  composer.addPass(output);

  const post: ConsolePost = {
    composer,
    renderPass,
    bloom,
    composite,
    output,
    strength: 1,

    setScene(scene: THREE.Scene, camera: THREE.Camera): void {
      renderPass.scene = scene;
      renderPass.camera = camera;
    },

    setStrength(x: number): void {
      const s = Math.max(0, x);
      post.strength = s;
      composite.uniforms.uStrength.value = s;
      bloom.strength = bloomStrength * (0.55 + 0.45 * Math.min(2, s));
    },

    setSize(width: number, height: number, pixelRatio: number): void {
      composer.setPixelRatio(pixelRatio);
      composer.setSize(width, height);
      bloom.resolution.set(width, height);
      const res = composite.uniforms.uResolution.value as THREE.Vector2;
      res.set(width * pixelRatio, height * pixelRatio);
    },

    update(elapsed: number): void {
      composite.uniforms.uTime.value = elapsed;
    },

    dispose(): void {
      composer.dispose();
      bloom.dispose();
      composite.material.dispose();
      composite.fsQuad.dispose();
      output.dispose();
      placeholderScene.clear();
    },
  };

  post.setSize(w, h, renderer.getPixelRatio());
  return post;
}
